/**
 * A post as a card: cover picture, category, title, excerpt, author line and a read link. Axes: layout
 * (vertical, horizontal), media (image, none), meta (full, short: the date only, news: date and title only),
 * density.
 */
import { type ReactNode } from "react";
import { Box } from "../primitives/box/box";
import { Card } from "../primitives/card/card";
import { CardContent } from "../primitives/card/card-content";
import { Group } from "../primitives/group/group";
import { Link } from "../primitives/link/link";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { MediaFrame } from "../components/media-frame";
import { defaults } from "../presets/defaults";
import { cn, tpl } from "../utils";
import type { Post, PostLabels } from "./post-card.types";

export type PostCardProps = {
  post: Post;
  labels: PostLabels;
  layout?: "vertical" | "horizontal";
  media?: "image" | "none";
  meta?: "full" | "short" | "news";
  density?: "default" | "compact";
};

export function PostCard({
  post,
  labels,
  layout = "vertical",
  media = "image",
  meta = "full",
  density = "default",
}: PostCardProps) {
  return (
    <>
      {((meta as string) === "news") ? (
        <Box
          className={cn(
            "flex flex-col gap-2 overflow-hidden rounded p-0 inset-ring inset-ring-border",
            defaults.news.card
          )}
          data-testid="item"
          data-layout={layout}
          data-meta="news"
        >
          <Box className={cn("relative shrink-0 overflow-hidden", defaults.news.cover)} data-testid="news-cover">
            <MediaFrame alt={post.title} ratio="16/9" className={cn("size-full", defaults.media.rounded)} />
            <Title
              as={3}
              size="xs"
              weight="semibold"
              className={cn(
                "pointer-events-none absolute inset-x-12 line-clamp-2 text-center leading-5 text-foreground",
                defaults.news.title
              )}
              data-testid="news-title"
            >
              {post.title}
            </Title>
          </Box>
          <Group
            gap="2"
            align="center"
            className={cn("w-full px-2 text-muted-foreground", defaults.news.strip)}
            data-testid="news-date"
          >
            <LucideIcon name="calendar" size={16} />
            <Text size="xs" weight="bold" className="leading-4">
              {post.date}
            </Text>
            {post.category ? (
              <Text size="xs" weight="bold" className="leading-4">
                {post.category}
              </Text>
            ) : null}
          </Group>
        </Box>
      ) : (
        <Card
          variant="default"
          className={cn(
            "h-full gap-4 overflow-hidden",
            (((layout as string) === "horizontal") ? "flex flex-col sm:flex-row" : "flex flex-col")
          )}
          data-testid="item"
          data-layout={layout}
          data-meta={meta}
        >
          {((media as string) === "image") ? (
            <Box className={cn("relative shrink-0", (((layout as string) === "horizontal") ? "sm:w-64" : ""))}>
              <MediaFrame alt={post.title} ratio="16/9" className="h-full" />
            </Box>
          ) : null}
          <CardContent className="flex flex-1 flex-col gap-2">
            {((meta as string) !== "news") ? (
              <Group gap="2" align="center">
                <LucideIcon name={post.icon} size={16} />
                <Text size="xs" className="uppercase tracking-wide text-muted-foreground">
                  {post.category}
                </Text>
              </Group>
            ) : null}
            <Title as={3} size="xl" weight="bold">
              {post.title}
            </Title>
            {(((density as string) === "default") && ((meta as string) !== "news")) ? (
              <Text size="sm" className="text-muted-foreground">
                {post.excerpt}
              </Text>
            ) : null}
            {((meta as string) !== "news") ? (
              <Group gap="2" className="mt-auto flex-wrap pt-2 text-muted-foreground">
                {((meta as string) === "full") ? (
                  <Text size="xs">
                    {tpl(labels.by, post.author)}
                  </Text>
                ) : null}
                <Text size="xs">
                  {post.date}
                </Text>
                {((meta as string) === "full") ? (
                  <Text size="xs">
                    {tpl(labels.minutes, post.minutes)}
                  </Text>
                ) : null}
              </Group>
            ) : null}
            {((meta as string) !== "news") ? (
              <Link href="#/" variant="default" data-testid="read">
                {labels.read}
              </Link>
            ) : null}
          </CardContent>
        </Card>
      )}
    </>
  );
}

